$\mathcal{H}(f)$, defined in (3.5) and (3.3), admits the following homogeneous expansion:
\begin{align*}
\mathcal{H}(f) = \mathcal{H}_2(f)+\mathcal{H}_3(f)+\mathcal{H}_4(f)+\mathcal{H}_{\ge 5}(f),
\end{align*}
where 
\begin{equation}
\begin{aligned}
\mathcal{H}_2(f)&:= -\frac{1}{4}\int_{\mathbb{T}} f\Lambda^{\alpha-1}f d\theta + \frac{1}{8}T_\alpha\int_{\mathbb{T}} f^2 d\theta,\\
 \mathcal{H}_3(f)&:= \frac{\alpha}{16}\int_{\mathbb{T}} f^2 \Lambda^{\alpha-1}fd\theta   -\frac{\alpha}{48}T_\alpha\int_{\mathbb{T}} f^3d\theta,\\
\mathcal{H}_4(f) &:=-\frac{\alpha(\alpha+4)}{192}\int_{\mathbb{T}} f^3\Lambda^{\alpha-1}fd\theta -\frac{\alpha^2}{256}\int_{\mathbb{T}} f^2 \Lambda^{\alpha-1}(f^2)d\theta + \frac{\alpha}{384}\int_{\mathbb{T}} M_{4}(f)(\theta)d\theta\\
& +  \frac{\alpha(2+\alpha)T_\alpha}{384}\int_{\mathbb{T}} f(\theta)^4 d\theta,
\end{aligned}
\end{equation}
where 
\begin{align}
T_\alpha = m_{2,\alpha}(0) \text{ (see (2.68))},\quad M_4(f)(\theta):=\int_{\mathbb{T}}(2-2\cos(\theta-\eta))^{-1-\frac{\alpha}{2}}(f(\theta)-f(\eta))^4d\eta, \quad \Lambda^{\alpha-1}\text{ is as in (2.67).}
\end{align}
$\mathcal{H}_{\ge 5}$ collects all the terms homogeneous of degree at least $5$ in $f$ and its gradient is of the form:
\begin{equation}
\begin{aligned}
\nabla \mathcal{H}_{\ge 5}(f) &= \int (2-2\cos(\theta-\eta))^{-\frac{\alpha}{2}}F_{1,\ge3}(f(\theta),f(\eta),J(\theta,\eta))(f(\theta)-f(\eta))d\eta \\
& \ +\int (2-2\cos(\theta-\eta))^{1-\frac{\alpha}{2}}F_{2,\ge4}(f(\theta),f(\eta))d\eta,
\end{aligned}
\end{equation}
where $J(\theta,\eta):=\frac{(f(\theta)-f(\eta))^2}{2-2\cos(\theta-\eta)}$ for some  functions $F_{1,\ge 3}:\mathbb{R}^3\mapsto \mathbb{R}$ and $F_{2,\ge4}:\mathbb{R}^2\mapsto \mathbb{R}$ that are analytic functions near the origin and homogeneous of degree at least $3$ and $4$ respectively.

Let $S,S^{\perp}$ be fixed as in (4.6) satisfying tangent_2 and tangent_1. Then, there exists a symplectic transformation $\Phi^{WB}:L^2_0\mapsto L^2_0$ such that 
\begin{align}
H :=\mathcal{H}\circ \Phi^{WB}= H_2+H_3+H_4+H_5+H_{\ge 6},
\end{align}
where
\begin{enumerate}[label=\textbf{\arabic*}]
\item (Quadratic and cubic terms) we have
\begin{equation}
\begin{aligned}
&H_2(f)= \int_{\mathbb{T}}-\frac{1}{4} v\Lambda^{\alpha-1}v +\frac{T_\alpha}{8}v^2dx + \int_{\mathbb{T}}-\frac{1}{4} z\Lambda^{\alpha-1}z +\frac{T_\alpha}{8}z^2dx =:H_{2,0} + H_{2,2} \\
&H_3(f) = \frac{\alpha}{16}\int_\mathbb{T} v\left( 2z \Lambda^{\alpha-1}z + \Lambda^{\alpha-1}(z^2)  -T_\alpha z^2\right) dx  + \frac{\alpha}{16} \int_\mathbb{T} z^2 \Lambda^{\alpha-1}z -\frac{T_\alpha}{3}z^3dx =:H_{3,2} + H_{3,3}.
\end{aligned}
\end{equation}
\item (Quartic and quintic terms) We have $H_{4}(f) = H_{4,0} + H_{4,2} + H_{4,3}+H_{4,4}$ where
\begin{align}
H_{4,0}(f) &= 6\sum_{j_1\in S^{+}}H^{(3)}_{4,j_1,-j_1,j_1,-j_1}|v_{j_1}|^4 + 12\sum_{\substack{j_1,j_2\in S^+,\\  j_1\ne j_2}}H^{(3)}_{4,j_1,-j_1,j_2,-j_2}|v_{j_1}|^2|v_{j_2}|^2, \\
H^{(3)}_{4,j_1,-j_1,j_2,-j_2}&=\begin{cases}
H_{4,j_1,-j_1,j_2,-j_2} - \frac{3}{4}\frac{(j_1+j_2)(H_{3,j_1,j_2,-(j_1+j_2)})^2}{(j_1+j_2)\kappa_{j_1+j_2}-j_1\kappa_{j_1}-j_2\kappa_{j_2}} & \text{ if $j_1=j_2$,}\\
H_{4,j_1,-j_1,j_2,-j_2} - \frac{3}{4}\left( \frac{(j_1+j_2)(H_{3,j_1,j_2,-(j_1+j_2)})^2}{(j_1+j_2)\kappa_{j_1+j_2}-j_1\kappa_{j_1}-j_2\kappa_{j_2}} +\frac{(j_1-j_2)(H_{3,j_1,-j_2,-(j_1-j_2)})^2}{(j_1-j_2)\kappa_{j_1-j_2} - j_1\kappa_{j_1}+j_2\kappa_{j_2}}\right)& \text{ if $j_1\ne j_2$,}
\end{cases}\\
H_{4,2}(f) & :=  \mathcal{H}_{4,2}(f) + \mathfrak{H}_{1}(f) + \mathfrak{H}_2(f) \\
\mathfrak{H}_1(f) &:= \frac{3\alpha}{8}\int \left(v\Lambda^{\alpha-1}z + z\Lambda^{\alpha-1} v + \Lambda^{\alpha-1}(vz) - T_\alpha vz \right)\partial_x \Pi_{S}K_1(v,z)dx \\
\mathfrak{H}_2(f) &:=\frac{3\alpha}{16} \int \left( 2z\Lambda^{\alpha-1}z + \Lambda^{\alpha-1}(z^2) - T_\alpha z^2\right)\partial_x \Pi_{S^\perp}K_2(v,v)dx, \text{ where $K_1,K_2$ are as in (4.34),}\\
 H_{4,3}&=R(vz^3),\quad H_{4,4}=R(z^4),\\
H_{5}(f) &=\sum_{i=2}^5H_{5,i}= \sum_{i=2}^5R(v^{5-i}z^i),
\end{align}
and $H_{\ge 6}$ collects all the terms homogeneous of degree at least $6$.
\item  There exists a finite dimensional space $E$ of the form in (4.9) such that $\Phi^{WB}(f) = f + \Psi(f) $ where $\Psi$ satisfies $\Psi(f) = \Pi_E \Psi(\Pi_E f)$. 
\item  $\Phi^{WB}$ is real, reversibility preserving and $\frac{2\pi}{\mathtt{M}}$-translation invariance preserving. 
\item  $H$ is $\mu_1$-regular for some $\mu_1=\mu_1(\alpha)>0$.
\end{enumerate}

Let $H$ be the Hamiltonian obtained in Proposition~4.4 and let $v_\varepsilon,U_\zeta$ and $H_{\zeta}$  be as in  (5.2) and (5.3). Then we have that for some constant $C_\varepsilon(\zeta)$, 
\begin{align}
H_{\zeta}(\theta,y,z) = C_\varepsilon(\zeta) + 2\pi{\omega(\zeta)}\cdot y + \mathcal{N}(\theta)(z,z) + P(\theta,y,z),
\end{align} 
where
\begin{align}
&\omega(\zeta) := \left( \overline{\omega} + \frac{6\varepsilon^2}{\pi}\mathbb{A}\zeta  \right), \text{ where $\overline{\omega}\in\mathbb{R}^\nu$ and $\mathbb{A}\in \mathbb{R}^{\nu\times\nu}$ are in (5.9) and (5.10)},\\
& \mathcal{N}(\theta)(z,z) :=H_{2,2}(z) +\varepsilon H_{3,2}(v_\varepsilon(\theta,0)+z) + \varepsilon^2H_{4,2}(v_\varepsilon(\theta,0)+z),\\
&P(\theta,y,z) := \varepsilon\left( H_{3,2}( v_\varepsilon(\theta,y)+z) - H_{3,2}(v_\varepsilon(\theta,0)+z)\right) + \varepsilon^2 \left( H_{4,2}(v_\varepsilon(\theta,y)+z) - H_{4,2}(v_\varepsilon(\theta,0) + z)\right)\\
& \quad \quad \quad \quad \  +6\varepsilon^{2b}y^T \mathbb{A}y + \varepsilon^{-2b}\left( H_{3,3} +  \sum_{i=3}^4H_{4,i}+\sum_{i=2}^{5}{H_{5,i}} + H_{\ge6}\right)\circ U_\zeta.
\end{align}

Given $\mathtt{p}$ in (6.24), let us fix the tangential sites $S$ as in (4.5), that is, fix $S_0^+$ and $\mathtt{M}$ so that tangent_2,tangent_1 and the hypotheses hypos1s1-hypothsdj22 hold. Then there exists $\varepsilon_0=\varepsilon_0(\mathtt{p},S^+_0,\mathtt{M},b)>0$ such that 
 for all $\varepsilon \in (0,\varepsilon_0)$,  there exist a Cantor-like  set $\mathcal{C}_\varepsilon\subset \Omega_\varepsilon$ (see (5.25)) such that
\begin{align}
\lim_{\varepsilon\mapsto 0}\frac{\left| \mathcal{C}_\varepsilon \right|}{\left| \Omega_\varepsilon \right|} = 1,
\end{align}
and for each $\omega\in \mathcal{C}_\varepsilon$, there exists a reversible, $\frac{2\pi}{\mathtt{M}}$-translation invariant embedding $i_\infty(\omega)\in H_{\varphi}^{s_0}\times H_{\varphi}^{s_0}\times H_{\varphi,x}^{s_0}$ which solves (6.1). Furthermore,  $i_\infty(\omega)$ is linearly stable under $\frac{2\pi}{\mathtt{M}}$-translation invariant perturbations.

Let $\mathtt{S}\gg s_0$, $\mathtt{C}>0$ be fixed. There exist $\mu_\mathtt{p}=\mu_{\mathtt{p}}(\mathtt{p})>0$ and $\varepsilon_0=\varepsilon_0(\mathtt{p},\mathtt{M},S_0,\mathtt{S},b,\mathtt{C})>0$ such that if a reversible, $\frac{2\pi}{\mathtt{M}}$-translation invariant embedding $i_0$ satisfies (7.3) for $\mu=\mu_\mathtt{p}$ and $\varepsilon\in (0,\varepsilon_0)$ for some $\Omega_1\subset \Omega_0$, then the following holds:
There exist a set of frequencies $\Omega_\infty=\Omega_\infty(i_0)\subset \Omega_1$  and a linear map $T(i_0)(\omega):Y_{i}\cap X_{i,\mathtt{M}}\mapsto X_{i}\cap X_{i,\mathtt{M}}$ for $\omega\in \Omega_{\infty}$ such that $T(i_0)(\omega)$ is an approximate inverse of $d_{i}X_{H_{\zeta}}(i_0(\omega))$. More precisely, for all $g(\omega)\in Y_{i}\cap X_{i,\mathtt{M}}$, it holds that $T(i_0)(\omega)[g(\omega)]\in X_i\cap X_{i,\mathtt{M}}$ and  (denoting $\le_{\mathtt{p},b,\mathtt{M},S_0,\mathtt{S},\mathtt{C}}$ by $\le$)
\begin{align}
\rVert &\left(d_{i}\mathcal{F}_\omega(i_0)\circ T(i_0) - I\right)[g]\rVert_s^{\text{Lip}(\gamma,\Omega_\infty)}\\
& \le \varepsilon^{2b-1}\gamma^{-2}\left(\rVert Z\rVert_{s_0+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)}\rVert g\rVert_{s+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)} + (\rVert Z\rVert_{s+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)} + \varepsilon^7\gamma^{-4}\rVert Z\rVert_{s_0+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)}\rVert \mathfrak{I}_0\rVert_{s+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)})\rVert g\rVert_{s_0+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)}\right),
\end{align}
and
\begin{align}
\rVert T(i_0)[g] \rVert_s^{\text{Lip}(\gamma,\Omega_\infty)} \le  \gamma^{-1}\left( \rVert g \rVert_{s+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)} + \varepsilon^{7}\gamma^{-4}\rVert \mathfrak{I}_0\rVert_{s+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)} \rVert g \rVert_{s_0+\mu_\mathtt{p}}^{\text{Lip}(\gamma,\Omega_\infty)} \right),
\end{align}
for all $s\in [s_0,\mathtt{S}]$.

Given $\mathtt{S}\gg s_0$, there exist constants $\mu_{\mathtt{p},0}=\mu_{\mathtt{p},0}(\mathtt{p})\ge 0$, $\varepsilon_0=\varepsilon_0(\mathtt{pe},\mathtt{S})>0$ and  a set $\Omega_{\infty}=\Omega_\infty(i_0)\subset\Omega_1$  such that if (7.3) holds for some $\mu=\mu_{\mathtt{p},0},\mathtt{C}>0$ and $\varepsilon\in (0,\varepsilon_0)$, then for all $\omega\in \Omega_\infty$, $\mathcal{L}_\omega:X_{\perp}\cap X_{\mathtt{M}}\mapsto Y_{\perp}\cap X_{\mathtt{M}}$ is invertible. More precisely,  given $f(\omega)\in Y_{\perp}\cap X_{\mathtt{M}} $, there exists $w(\omega)\in X_{\perp}\cap X_{\mathtt{M}}$ such that $\mathcal{L}_\omega[w(\omega)] = f(\omega)$ for each $\omega\in \Omega_\infty$ and 
\begin{align}
\rVert w \rVert_s^{\text{Lip}(\gamma,\Omega_\infty)} = \rVert \mathcal{L}_\omega^{-1}[g]\rVert_s^{\text{Lip}(\gamma,\Omega_\infty)} \le_{\mathtt{pe},\mathtt{S}} \gamma^{-1}\left(\rVert f \rVert^{\text{Lip}(\gamma,\Omega_\infty)}_{s+\mu_{\mathtt{p},0}} +\varepsilon^{7}\gamma^{-4}\rVert \mathfrak{I}_0 \rVert^{\text{Lip}(\gamma,\Omega_\infty)}_{s+\mu_{\mathtt{p},0}}\rVert f \rVert^{\text{Lip}(\gamma,\Omega_\infty)}_{s_0+\mu_{\mathtt{p},0}}\right),
\end{align}
for all $s\in [s_0,\mathtt{S}]$.

There exists $\varepsilon_0=\varepsilon_0({\mathtt{p},b,\mathtt{M},S_0})>0$ such that for all $\varepsilon\in (0,\varepsilon_0)$, and for all $n\ge 0$, 
\begin{enumerate}[label=(\arabic*)]
\item  $Z_{n}(\omega):=\mathcal{F}_\omega(i_{n}(\omega))$ is well-defined for $\omega\in \mathcal{G}_n$ and $Z_n(\omega)\in Y_i\cap X_{i,\mathtt{M}}$. It also satisfies
\begin{align}
\rVert Z_{n}\rVert_{s_0}^{\text{Lip}(\gamma,\mathcal{G}_{n})}&\le_{\mathtt{p},b,\mathtt{M},S_0} \varepsilon^{6-2b}N_{n-1}^{-\sigma_4},\\
\rVert Z_{n}\rVert_{s_0+\mathtt{b}_1-\mu_{\mathtt{p}}}^{\text{Lip}(\gamma,\mathcal{G}_n)}&\le_{\mathtt{p},b,\mathtt{M},S_0} \varepsilon^{6-2b}N_{n-1}^{\mathtt{k}},
\end{align}
Furthermore, we have 
\begin{align}
\rVert Z_{n}\rVert_{s_0 + \mu_{\mathtt{p}}}^{\text{Lip}(\gamma,\mathcal{G}_{n})}&\le_{\mathtt{p},b,\mathtt{M},S_0} \varepsilon^{6-2b}N_{n-1}^{-\sigma_5},
\end{align}

\item  $\mathfrak{I}_{n+1}=\mathfrak{I}_{n+1}(\omega)$ is well-defined for $\omega\in \mathcal{G}_{n+1}$ and  $\mathfrak{I}_{n+1}(\omega) \in X_i\cap X_{i,\mathtt{M}}$.  It also satisfies
\begin{align}
\rVert \widehat{\mathfrak{I}}_{n+1}\rVert^{\text{Lip}(\gamma,\mathcal{G}_{n+1})}_{s_0+2\mu_\mathtt{p}}&\le_{\mathtt{p},b,\mathtt{M},S_0} \varepsilon^{6-4b}N_{n-1}^{-\sigma_3},\\
 \rVert \widehat{\mathfrak{I}}_{n+1}\rVert^{\text{Lip}(\gamma,\mathcal{G}_{n+1})}_{s_0+2\mu_\mathtt{p}+\mathtt{b}_1}&\le_{\mathtt{p},b,\mathtt{M},S_0} \varepsilon^{6-4b}N_{n}^{\mathtt{k}} 
\end{align}


\end{enumerate}

The linear operator $\mathcal{L}_\omega$ in (7.31) has the form:
 \begin{align}
 \mathcal{L}_\omega h &= \mathcal{D}_\omega - \Pi_{S^\perp}\partial_xM[h] + \mathcal{R},\text{ with } M[h]:=\Lambda^{\alpha-1}_{-\frac{1}{2} + a_1} + \left(\frac{T_\alpha}{4}+a_2 \right)h + \Upsilon^{\alpha-3}_{a_3}
 \end{align}
 where
 \begin{enumerate}[label=(\arabic*)]
 \item $a_1,a_3\in \mathfrak{C}_2(i_0)$ and $a_2\in \mathfrak{C}_1(i_0)$ (see Definition~8.2 for the sets $\mathfrak{C}_1(i_0),\mathfrak{C}_2(i_0)$). Furthermore, $a_1,a_2,a_3$ are real-valued and 
 \begin{align}
 a_1(\varphi,x,y) = a_1(-\varphi,-x,-y),\quad a_3(\varphi,x,y) = a_3(-\varphi,-x,-y),\ a_2(\varphi,x) = a_2(-\varphi,-x).
 \end{align}
 \item $\mathcal{R}\in \mathfrak{R}(i_0)$. Specifically,
 \begin{align}
 \mathcal{R}(\varphi):=\varepsilon^2\partial_x \nabla_z^2\mathfrak{H}_1(\bar{v}(\varphi))[h] + \partial_xR(\varphi),
 \end{align}
 where $R$ is a finite dimensional operator satisfying (8.33).
 \item $\mathcal{L}_\omega$ is real, reversible (see Definition~2.46 for a reversible operator) and Hamiltonian (see Definition~2.40 for a Hamiltonian operator).

 \item   $\mathcal{L}$ is $\frac{2\pi}{\mathtt{M}}$-translation invariant and $a_1,a_2,a_3$ are also $\frac{2\pi}{\mathtt{M}}$-translation invariant, that is,
 \begin{align}
 \rho_{\mathtt{M}}(a_2)(\varphi,x) = a_2(\varphi,x),\quad \rho_{\mathtt{M}}(a_i)(\varphi,x,y) = a_i(\varphi,x,y),\text{ for $i=1,3$}, 
 \end{align}
where  $\rho_{\mathtt{M}}(a)(\varphi,x,y):=a(\varphi,x+\frac{2\pi}{\mathtt{M}},y+\frac{2\pi}{\mathtt{M}})$.

 \end{enumerate}
 \begin{proof}
 We first prove the expression of $\mathcal{L}_\omega$ in (8.50) and then give proofs for linsi1-linsi4. For $u(x)=u(\varphi,x)$, defined in (8.3),
 we compute $\nabla_z^{2}\mathcal{H}(u)[h]$.  From Proposition~3.2, it is clear that there exist  $F^1,F^2,F^3:\mathbb{R}^3\mapsto \mathbb{R}$, which are real analytic near $(0,0,0)$ such that $F^i(0,0,0)=0$ for $i=1,2,3$ and 
\begin{equation}
\begin{aligned}
\nabla^2_z \mathcal{H}(u)[h] &= -\frac{1}{2}\Lambda^{\alpha-1}h + \frac{T_\alpha}{4}h \\
& \  + \int_{\mathbb{T}}(2-2\cos(x-y))^{-\frac{\alpha}{2}}F^1(u(x),u(y),J(u)(x,y))(h(x)-h(y))dy\\
& \ + \int_{\mathbb{T}}(2-2\cos(x-y))^{-\frac{\alpha}{2}}F^2(u(x),u(y),J(u)(x,y))(u(x)-u(y))dyh(x)\\
& \ + \int_{\mathbb{T}}(2-2\cos(x-y))^{1-\frac{\alpha}{2}}F^3(u(x),u(y))h(y)dy,
\end{aligned}
\end{equation}
where $J(u)(x,y):=\frac{(u(x)-u(y))^2}{2-2\cos(x-y)}$.
 Let us denote
\begin{equation}
\begin{aligned}
&a_1(x,y) := F^1(u(x),u(y),J(u)(x,y)),\\
&a_2(x) =  \int_{\mathbb{T}}(2-2\cos(x-y))^{-\frac{\alpha}{2}}F^2(u(x),u(y),J(u)(x,y))(u(x)-u(y))dy,\\
&a_3(x,y) := F^3(u(x),u(y)),
\end{aligned}
\end{equation}
so that we have
\begin{align}
\nabla_z^2\mathcal{H}(u)[h] = \Lambda^{\alpha-1}_{-\frac{1}{2} + a_1}h + \left(\frac{T_\alpha}{4}+a_2\right)h + \Upsilon^{\alpha-3}_{a_3}h = M[h].
\end{align}
Note that $a_1,a_2,a_3$ depend on $\omega,\varphi$ and $i_0$ as well, since so does $u$ (see (8.3)).  Then, it follows from Lemma~8.17 and (8.3) that
\begin{align}
K_{02} = M[h] + \varepsilon^2\nabla_z^2\mathfrak{H}_1(\bar{v}(\varphi))[h] + R(\varphi),
\end{align}
where $R$ satisfies the estimates in (8.33).
From the definition of $\mathcal{L}_\omega$ in (7.31), we have
\[
\mathcal{L}_\omega = \mathcal{D}_\omega -\Pi_{S^\perp}\partial_xMh + \partial_x\mathcal{R},\quad \mathcal{R}:=\varepsilon^2\nabla_z^2\mathfrak{H}_1(\bar{v}(\varphi))[h] + R(\varphi),
\]
which gives the expression of $\mathcal{L}_\omega$ in (8.50).

We prove linsi2 first and then move on to linsi1, linsi3 and linsi4.

\textbf{Proof of linsi2.}
The decomposition $\mathcal{R}= \varepsilon^2\nabla_z^2\mathfrak{H}_1(\bar{v}(\varphi))[h] + R(\varphi)$, where $R$ satisfies (8.33), has just been proved above. Noticing $\nabla_z^2\mathfrak{H}_1(\bar{v}(\varphi))[h]$ is of the form in (8.31) (see (4.17) for the definition of $\mathfrak{H}_1$), it implies that $\mathcal{R}\in \mathfrak{R}(i_0)$.

\textbf{Proof of linsi1.}
It follows immediately from Lemma~8.3 that $a_1,a_3\in \mathfrak{S}_2(i_0)$ and $a_2\in \mathfrak{S}_1(i_0)$. Furthermore, $a_1,a_2,a_3$ are real, since $F^{1},F^2,F^3$ in (8.55) are real-valued functions. To prove the symmetry in (8.51),  note that $u\in X$, that is,
\[
u(-\varphi,-x)=u(\varphi,x),
\]
which follows from (8.3), Lemma~7.1, item3_normal_2 of Proposition~4.4, and (5.2). Hence, (8.51) follows straightforwardly from (8.55).

\textbf{Proof of linsi3.}
Clearly, $K$ is a real-valued Hamiltonian (see (7.18)) since $H_\zeta$ is a real-valued Hamiltonian.
$K$ is a reversible Hamiltonian, since $H_\zeta$ is reversible (Lemma~5.3), $G_\delta$ is reversibility preserving (Lemma~7.6) and $K=H_\zeta\circ G_\delta$, which is given in (7.18).  From the definition of $\mathcal{L}_\omega$, and Lemma~2.50, we see that $\mathcal{L}_\omega$ is reversible. Furthermore, since $K_{02}$ is a symmetric operator (because it is a Hessian of a Hamiltonian, thanks to (8.1)_1}), $\mathcal{L}_\omega$ (see (7.31)) is a Hamiltonian operator.


\textbf{Proof of linsi4.} Lemma~7.11 imples that $K_{02}$ in (8.1)_1} is  $\frac{2\pi}{\mathtt{M}}$-translation invariant, and therefore so is $\mathcal{L}_\omega$ in (7.31), since $\mathcal{D}_\omega$ does not destroy this property. Since $i_\delta$ is $\frac{2\pi}{\mathtt{M}}$-translation invariant, it follows from item3_normal_2 of Proposition~4.4, (5.22) and (8.3) that $u$ is $\frac{2\pi}{\mathtt{M}}$-translation invariant. Then, (8.53) follows immediately from (8.55).
 \end{proof}

There exists a constant 
 \begin{align}
 \mu_{\mathtt{p},1} \ge 0, \text{ depending only on $\mathtt{p}$ in (6.24)},
 \end{align}
 such that  if (7.3) is satisfied with $\mu =\mu_{\mathtt{p},1}$ and for some $\mathtt{C}>0$, then the followings hold:
$\mathcal{L}^6$ in (10.237) can be written as
 \begin{align}
L_0:= \mathcal{L}^6 = \mathcal{D}_\omega -D_0 + \mathcal{R}_0,
 \end{align}
 where the operators $D_0$ and $\mathcal{R}_0$ satisfy
 \begin{enumerate}[label=(\arabic*)]
 \item  $D_0$ is a diagonal operator between $H_{S^\perp}$ and $H_{S^\perp}$ such that 
 \begin{align}
 D_0 &= Op^W(d_0(\omega,\xi)),\quad d_0({\omega,\xi}):=\text{i}\left( \mathtt{m}_\alpha(\omega)\lambda_\alpha(\xi) +  \xi \frac{T_\alpha}4 + \mathfrak{m}_{1}(\omega,\xi) \right),\\
 \mathfrak{m}_{1} &:= \xi\left(\mathfrak{m}_{\le 0}(\omega,\xi) + \varepsilon^2\mathfrak{m}_{\mathfrak{b}}(\xi)\right)\in \mathcal{S}^1, 
 \end{align}
 and  $\mathtt{m}_{\alpha}=-\frac{1}{2}+\varepsilon^2\mathtt{m}_{\alpha,1}+\mathtt{m}_{\alpha,2}$ satisfies \begin{align}
 |\mathtt{m}_{\alpha,1}|^{\text{Lip}(\gamma,\Omega_1)} \le_{\mathtt{pe}} 1,\quad |\mathtt{m}_{\alpha,2}|^{\text{Lip}(\gamma,\Omega_1)}\le_{\mathtt{pe}} \varepsilon^{7-4b},\quad |d_i\mathtt{m}_{\alpha,2}(i_0)[\hat{\textbf{\i}}]|\le_{\mathtt{pe}} \varepsilon\rVert \hat{\textbf{\i}}\rVert_{s_0+\mu_{\mathtt{p},1}},
 \end{align} and  $\mathfrak{m}_1(\omega,\xi)$ satisfies
 \begin{align}
 |\mathfrak{m}_1|^{\text{Lip}(\gamma,\Omega_1)}_{1,0,2}&\le_{\mathtt{pe}}  \varepsilon^2,\quad |d_i\mathfrak{m}_1(i_0)[\hat{\textbf{\i}}]|_{1,0,2}\le_{\mathtt{pe}} \varepsilon \rVert \hat{\textbf{\i}} \rVert_{s_0+\mu_{\mathtt{p},1}}.
 \end{align}

  \item  Given $\mathtt{S}\gg s_0$, there exists $\varepsilon_0=\varepsilon_0(\mathtt{pe},\mathtt{S})$ such that if $\varepsilon \in (0,\varepsilon_0)$, then $\mathcal{R}_0$ is a Lip-$0$-modulo tame operator up $\mathtt{S}$ and $d_i\mathcal{R}_0(i_0)[\hat{\textbf{\i}}]$ is a $0$-tame operator  and satisfies the following estimates:
  \begin{align}
  \sup_{\vec{b}\in \mathbb{N}_0^{\nu},\ |\vec{b}|\le \mathtt{b}_0 }\mathfrak{M}^{\sharp,\gamma}_{\partial_{\varphi}^{\vec{b}}(\mathcal{R}_0)}(0,s)&\le_{\mathtt{pe},s} \gamma^{-1}\left(\varepsilon^5 + \varepsilon^3\rVert \mathfrak{I}_0\rVert^{\text{Lip}(\gamma,\Omega_1)}_{s+\mu_{\mathtt{p},1}}\right),\\
  \sup_{ \vec{{b}}\in\mathbb{N}_0^\nu,\ |\vec{{b}}|\le \mathtt{b}_0}\mathfrak{M}^\sharp_{\partial_\varphi^{\vec{b}}(d_i\mathcal{R}_0(i_0)[\hat{\textbf{\i}}])}(0,s_0)&\le_{\mathtt{pe}}\varepsilon^3\gamma^{-1}\rVert\hat{\textbf{\i}}\rVert_{s_0+\mu_{\mathtt{p},1}}, \end{align}
  for all $s\in [s_0,\mathtt{S}]$.
  \item  $ D_0$ is a real, reversible operator. Also, $\mathcal{R}_0$ is a real and  reversible operator.

  \item  There exist reversibility preserving real operators $\Phi_{1-6,1},\Phi_{1-6,2}:H_{S^\perp}\mapsto H_{S^\perp}$ such that
